command:
npm install --no-save --no-package-lock playwright@1.56.1 >/dev/null 2>&1
npx playwright install --with-deps chromium >/dev/null 2>&1
python3 -m http.server 8765 --bind 127.0.0.1 >/dev/null 2>&1 &
sleep 1
curl -s --max-time 60 "https://openrouter.ai/api/v1/models?sort=top-weekly" -o /tmp/live.json
export OUT=/tmp
cat > /tmp/live.cjs <<'JS'
process.env.MODELS_JSON = '/tmp/live.json';
const { chromium } = require(process.cwd() + '/node_modules/playwright');
const { openApp } = require(process.cwd() + '/tests/web/mock.cjs');
(async () => {
  const browser = await chromium.launch({ executablePath: process.env.CHROMIUM || undefined });
  const { page } = await openApp(browser, { viewport: { width: 1000, height: 1100 } });
  await page.waitForFunction(() => modelCatalog.entries.length > 100, null, { timeout: 30000 });
  const all = await page.evaluate(() => modelCatalog.entries.map((e) => ({ id: e.id, iq: e.intelligence, est: !!e.iqEstimated, basis: e.iqBasis || '', err: e.iqError || 0, arena: e.arena, coding: e.coding, agentic: e.agentic })));
  const withNum = all.filter((e) => typeof e.iq === 'number');
  console.log('MODELS', all.length, '| exact', withNum.filter((e) => !e.est).length, '| estimated', withNum.filter((e) => e.est).length, '| none', all.length - withNum.length);
  const anyBench = (e) => [e.coding, e.agentic, e.arena].some((v) => typeof v === 'number');
  const missed = all.filter((e) => typeof e.iq !== 'number' && anyBench(e));
  console.log('WITH A BENCHMARK BUT NO NUMBER (out of range):', missed.length, JSON.stringify(missed.map((e) => e.id + ' arena=' + e.arena + ' coding=' + e.coding + ' agentic=' + e.agentic)));
  const basisCount = {}; withNum.filter((e) => e.est).forEach((e) => { basisCount[e.basis] = (basisCount[e.basis] || 0) + 1; });
  console.log('ESTIMATES BY BASIS', JSON.stringify(basisCount));
  console.log('--- DeepSeek rows in the picker (what the user sees) ---');
  await page.click('#model-menu-btn');
  await page.waitForSelector('.model-card');
  await page.fill('#model-search', 'deepseek').catch(() => {});
  const searchSel = await page.evaluate(() => { const i = document.querySelector('#model-menu-popup input[type=search], #model-menu-popup input[type=text]'); return i ? (i.id || i.className) : ''; });
  if (searchSel) { await page.evaluate(() => { const i = document.querySelector('#model-menu-popup input[type=search], #model-menu-popup input[type=text]'); i.value = 'deepseek'; i.dispatchEvent(new Event('input', { bubbles: true })); }); }
  await page.waitForTimeout(400);
  const rows = await page.evaluate(() => Array.from(document.querySelectorAll('.model-card')).filter((c) => /deepseek/i.test(c.dataset.modelId)).map((c) => { const g = c.querySelector('.model-gauge'); return c.dataset.modelId.replace('deepseek/', '') + ' => ' + (g ? (g.classList.contains('none') ? 'SIN BENCHMARK (—)' : c.querySelector('.model-gauge-num').textContent + (g.classList.contains('est') ? '  [estimado: ' + g.title.replace(/^Índice de inteligencia estimado /, '').slice(0, 95) + '…]' : '  [exacto]')) : 'SIN FILA DE GAUGE'); }));
  rows.forEach((r) => console.log('  ' + r));
  console.log('search box found:', JSON.stringify(searchSel));
  await browser.close();
})();
